-- Upload-ready SQL for 5 completed generated posts

-- sql: 10000010002017-tape20
START TRANSACTION;
SET @existing_post=(SELECT ID FROM `ha_posts` WHERE `post_name`='خشکرود-مرکزی-navar-tip-20cm' OR (`post_type`='arak' AND `post_title`='خرید نوار تیپ ۲۰ سانتی در خشکرود') LIMIT 1);
SET @post_id=COALESCE(@existing_post,LAST_INSERT_ID());
COMMIT;


